import json
colors=[2,3,4,6,7]
rows=[]
for c in colors:
    for pat in ['..c.','cccc','.cc.','..c.']:
        row=[]
        for j in range(5):
            row.extend([0 if x=='.' else c for x in pat])
            if j<4: row.append(5)
        rows.append(row)
    if c != colors[-1]: rows.append([5]*24)
print(json.dumps(rows,separators=(',',':')))

